## 3. Plan de Pruebas Unitarias e Integración (Vitest)

Validaremos que los hooks de estado global de la nueva interfaz y los transformadores de datos respeten las reglas de negocio y no expongan datos entre tenants.

```typescript
// src/tests/dian-transformer.test.ts
import { describe, it, expect } from 'vitest';
import { DianTransactionSchema } from '../schemas/dianTransactionSchema';

describe('SPEC-033: Validación de Esquemas y Consistencia Tributaria', () => {
  it('Debe rechazar transacciones sin tenant_id (Violación RLS)', () => {
    const payload = {
      tenant_id: "", // Inválido
      customer_nit: "900123456",
      items: [{ product_id: "123e4567-e89b-12d3-a456-426614174000", quantity: 2, unit_price: 15000, tax_rate: "19.00" }],
      payment_method: "CASH",
      total_amount: 35700,
    };

    const result = DianTransactionSchema.safeParse(payload);
    expect(result.success).toBe(false);
    if (!result.success) {
      expect(result.error.format().tenant_id?._errors).toContain("Contexto de tenant requerido por RLS");
    }
  });

  it('Debe aceptar un payload de factura DIAN totalmente válido', () => {
    const validPayload = {
      tenant_id: "a0000000-0000-0000-0000-000000000001",
      customer_nit: "800987654-1",
      items: [
        {
          product_id: "123e4567-e89b-12d3-a456-426614174000",
          quantity: 1,
          unit_price: 50000,
          tax_rate: "5.00",
          retention_applicable: true
        }
      ],
      payment_method: "TRANSFER",
      total_amount: 52500,
    };

    const result = DianTransactionSchema.safeParse(validPayload);
    expect(result.success).toBe(true);
  });
});
```

